-- Member 2 - Feature 10: Outfit Builder & Digital Lookbook.
--
-- Non-destructive and repeatable: every statement uses IF NOT EXISTS / ON CONFLICT,
-- so running this file again never drops, truncates or rewrites existing data.
-- Run with:  node scripts/member2-migrate.js   (reads M2_DATABASE_URL or DATABASE_URL)
-- or:        psql "<connection string>" -f src/modules/discovery/sql/m2_001_lookbooks.sql
--
-- IDs are generated by the application (crypto.randomUUID), so no extension is required.

BEGIN;

CREATE TABLE IF NOT EXISTS m2_lookbooks (
  id          UUID PRIMARY KEY,
  owner_id    TEXT NOT NULL CHECK (length(owner_id) BETWEEN 1 AND 100),
  name        TEXT NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 80),
  occasion    TEXT CHECK (occasion IS NULL OR length(occasion) <= 60),
  notes       TEXT CHECK (notes IS NULL OR length(notes) <= 500),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS m2_lookbooks_owner_idx ON m2_lookbooks (owner_id, updated_at DESC);

-- Garments referenced by a lookbook. listing_id is intentionally NOT a foreign key:
-- listings live in Member 1's module (currently in memory) and may be sold or removed.
-- `snapshot` keeps the garment's details at save time so a lookbook still renders
-- gracefully when the listing later disappears.
CREATE TABLE IF NOT EXISTS m2_lookbook_items (
  lookbook_id UUID NOT NULL REFERENCES m2_lookbooks (id) ON DELETE CASCADE,
  listing_id  TEXT NOT NULL CHECK (length(listing_id) BETWEEN 1 AND 100),
  slot        TEXT NOT NULL CHECK (slot IN ('outerwear', 'top', 'layer', 'bottom', 'accessory', 'other')),
  position    SMALLINT NOT NULL CHECK (position BETWEEN 0 AND 7),
  snapshot    JSONB NOT NULL,
  PRIMARY KEY (lookbook_id, listing_id),
  UNIQUE (lookbook_id, position)
);

CREATE TABLE IF NOT EXISTS m2_schema_migrations (
  version    TEXT PRIMARY KEY,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO m2_schema_migrations (version) VALUES ('m2_001_lookbooks') ON CONFLICT (version) DO NOTHING;

COMMIT;
